window.docContents[41].resolve({"/Output-Formats/#html-conventions-css":{"contents":"The names of CSS variables that are intended for customization begin with --verso-, with a single - before the variable's name.\nVariables that are a part of the Verso implementation and are not intended to be directly customized use two - characters, and thus begin with --verso--.\n\nThe customizable variables and their default values are defined in verso-vars.css, which is included as the string constant Html.«verso-vars.css».\nEach page should include this stylesheet.\n\nCSS variables used by all genres that should support HTML output.\n\n","context":"Writing Documentation in Lean with Verso\u0009Output Formats\u0009HTML\u0009Conventions","header":"5.1.1.1. CSS","id":"/Output-Formats/#html-conventions-css"}});